// Verification functions
use pinocchio::program_error::ProgramError;
use groth16_solana::groth16::Groth16Verifier;
use crate::instructions::types::{CommitmentProofData, WithdrawProofData};
use pinocchio_log::log;

pub fn verify_commitment_proof(proof_data: &CommitmentProofData) -> bool {
    // Prepare public inputs in circuit order: [commitment, nullifierHash, value, label]
    let public_inputs = [
        proof_data.commitment,
        proof_data.nullifier_hash,
        proof_data.value,
        proof_data.label,
    ];
    
    log!("Verifying commitment proof");
    log!("  proof_a length: {}", proof_data.proof_a.len());
    log!("  proof_b length: {}", proof_data.proof_b.len());
    log!("  proof_c length: {}", proof_data.proof_c.len());
    
    // Create verifier with commitment verifying key
    log!("Creating Groth16 verifier");
    let mut verifier = match Groth16Verifier::new(
        &proof_data.proof_a,
        &proof_data.proof_b,
        &proof_data.proof_c,
        &public_inputs,
        &COMMITMENT_VERIFYINGKEY,
    ) {
        Ok(v) => v,
        Err(_) => {
            log!("Failed to create Groth16 verifier");
            return false;
        }
    };
    
    // Verify the proof
    match verifier.verify() {
        Ok(()) => {
            log!("Commitment proof verified successfully");
            true
        }
        Err(_) => {
            log!("Invalid commitment proof");
            false
        }
    }
}

pub fn verify_withdraw_proof(proof_data: &WithdrawProofData) -> bool {
    // Public signals for withdraw circuit - convert Vec to array slice
    let public_inputs = &proof_data.public_signals[..];
    
    log!("Verifying withdraw proof");
    log!("  proof_a length: {}", proof_data.proof_a.len());
    log!("  proof_b length: {}", proof_data.proof_b.len());
    log!("  proof_c length: {}", proof_data.proof_c.len());
    log!("  public_inputs count: {}", public_inputs.len());
    
    // Need to convert Vec to array for Groth16Verifier
    // For now, we'll handle up to 8 public inputs for withdraw
    if public_inputs.len() != 8 {
        log!("Invalid number of public inputs for withdraw: {}", public_inputs.len());
        return false;
    }
    
    let inputs_array: [_; 8] = [
        public_inputs[0],
        public_inputs[1],
        public_inputs[2],
        public_inputs[3],
        public_inputs[4],
        public_inputs[5],
        public_inputs[6],
        public_inputs[7],
    ];
    
    // Create verifier with withdraw verifying key
    log!("Creating Groth16 verifier for withdraw");
    let mut verifier = match Groth16Verifier::new(
        &proof_data.proof_a,
        &proof_data.proof_b,
        &proof_data.proof_c,
        &inputs_array,
        &WITHDRAW_VERIFYINGKEY,
    ) {
        Ok(v) => v,
        Err(_) => {
            log!("Failed to create Groth16 verifier for withdraw");
            return false;
        }
    };
    
    // Verify the proof
    match verifier.verify() {
        Ok(()) => {
            log!("Withdraw proof verified successfully");
            true
        }
        Err(_) => {
            log!("Invalid withdraw proof");
            false
        }
    }
}
